/* Phase H: reuse cover draft UI, authenticated parent bridge, NAS read/plan only.
 * No apply request is implemented. Indexed album artwork is NOT embedded cover proof. */
export function installTagCoverDraft({getAlbum,getSelectedFiles,api}){
 if(typeof getAlbum!=='function'||typeof getSelectedFiles!=='function'||typeof api!=='function')throw Error('tag_cover_requires_editor_context');
 const host=document.querySelector('.tags-panel'),albumHeader=document.querySelector('#albumHeader');
 if(!host||!albumHeader)throw Error('tag_cover_mount_missing');
 const region=document.createElement('section');region.className='tag-cover-draft';region.setAttribute('aria-label','내장 앨범 커버 편집 초안');
 region.innerHTML=`<div class="tag-cover-heading"><h3>내장 커버 관리</h3><span>파일 내장 앞표지 · 실제 저장 비활성</span></div>
 <p class="tag-cover-explanation">앨범 목록 커버는 NAS 색인·폴더 이미지일 수 있습니다. 아래 ‘현재 상태 조회’로 실제 FLAC/MP3의 내장 앞표지를 별도로 읽습니다. 0.jpg 등 폴더 커버는 변경하지 않습니다.</p>
 <div class="tag-cover-grid"><div><small>변경 예정 이미지</small><div class="tag-cover-art" id="tagCoverArt"><span>표지 초안 없음</span></div></div>
 <div class="tag-cover-details"><div class="tag-cover-actions"><button type="button" data-cover-inspect>현재 내장 커버 조회</button><button type="button" data-cover-action="add">이미지 추가 계획</button><button type="button" data-cover-action="replace">이미지 교체 계획</button><button type="button" data-cover-action="remove">앞표지 제거 계획</button><button type="button" data-cover-reset>취소</button></div>
 <input type="file" id="tagCoverFile" accept="image/png,image/jpeg" hidden><div id="tagCoverStatus" role="status" aria-live="polite"></div><div id="tagCoverFiles" class="tag-cover-files"></div>
 <button type="button" data-cover-plan>NAS 변경 계획 확인 · 저장 없음</button><button type="button" class="tag-cover-apply" disabled title="이번 운영 연결에는 음원 쓰기 경로가 없습니다.">실제 파일에 저장 · 비활성</button></div></div>
 <div class="tag-cover-current" aria-label="원본과 변경 예정 커버 비교"></div>`;
 albumHeader.insertAdjacentElement('afterend',region);region.hidden=true;
 const q=s=>region.querySelector(s),fileInput=q('#tagCoverFile'),art=q('#tagCoverArt'),status=q('#tagCoverStatus'),files=q('#tagCoverFiles'),current=q('.tag-cover-current');
 const controls=[...region.querySelectorAll('[data-cover-action]')];
 let albumId='',draft=null,objectUrl=null,intent=null,version=0,selectionKey='',busy=false,states=new Map(),plans=new Map();
 const selected=()=>getSelectedFiles();const name=f=>f.split('/').pop();
 const revoke=()=>{if(objectUrl){URL.revokeObjectURL(objectUrl);objectUrl=null;}};
 function reset(){++version;revoke();draft=null;intent=null;plans.clear();fileInput.value='';render();}
 function sync(){const id=getAlbum()?.id||'',key=JSON.stringify([id,...selected()]);if(key!==selectionKey){selectionKey=key;++version;states.clear();plans.clear();}if(id!==albumId){albumId=id;revoke();draft=null;}region.hidden=!id;}
 function text(tag,value,cls){const el=document.createElement(tag);el.textContent=value;if(cls)el.className=cls;return el;}
 function render(){sync();const chosen=selected();controls.forEach(b=>{b.disabled=busy||!chosen.length;b.setAttribute('aria-pressed',String(draft?.action===b.dataset.coverAction));});q('[data-cover-inspect]').disabled=busy||!chosen.length||chosen.length>10;q('[data-cover-plan]').disabled=busy||!draft||!chosen.length||chosen.length>10;
  art.replaceChildren();if(draft?.url){const img=document.createElement('img');img.src=draft.url;img.alt='변경 예정 내장 앞표지';art.append(img);}else art.append(text('span',draft?.action==='remove'?'앞표지 제거 예정':'표지 초안 없음'));
  files.replaceChildren(text('p',`대상 ${chosen.length}곡: ${chosen.slice(0,5).map(name).join(', ')}${chosen.length>5?' 외 '+(chosen.length-5)+'곡':''}`));
  files.append(text('p',chosen.length>1?'여러 곡 비교만 가능합니다. 최초 실제 저장은 별도 승인 후 한 곡으로 제한합니다.':'실제 저장은 별도 승인 후에만 활성화합니다.','tag-cover-warning'));
  if(chosen.length>10)files.append(text('p','한 번에 최대 10곡까지 조회·계획합니다. 선택을 줄여 주세요.','tag-cover-warning'));
  status.textContent=busy?'NAS에서 현재 파일을 확인하는 중…':draft?`${{add:'추가',replace:'교체',remove:'제거'}[draft.action]} 초안 · ${draft.filename||'새 이미지 없음'}${draft.width?' · '+draft.width+'×'+draft.height:''} · 실제 쓰기 없음`:'현재 내장 커버는 아직 확인하지 않았습니다. 조회 후 계획을 검토하세요.';
  current.replaceChildren();for(const file of chosen.slice(0,10)){const row=document.createElement('article');row.append(text('strong',name(file)));const state=states.get(file),plan=plans.get(file);if(!state){row.append(text('p','내장 커버 미조회 · 앨범 색인 커버로 대체하지 않음'));}else if(state.state!=='EMBEDDED_COVER_INSPECTED'){row.append(text('p','HOLD: '+(state.reason||'현재 상태 확인 실패')));}else{
   const front=state.front_covers||[];row.append(text('p',`실제 내장 앞표지 ${front.length}개 · 기타 이미지 ${state.other_cover_count}개`));if(state.preview_data_url?.startsWith('data:image/jpeg;base64,')){const img=document.createElement('img');img.src=state.preview_data_url;img.alt=name(file)+' 원본 내장 앞표지';row.append(img);}row.append(text('p','파일 SHA256: '+state.file_sha256,'tag-cover-hash'));for(const pic of front)row.append(text('p',`${pic.mime} · ${pic.bytes} bytes · SHA256 ${pic.sha256}`,'tag-cover-hash'));
   if(draft)row.append(text('p',`변경 예정: ${{add:'앞표지 추가',replace:'앞표지 교체',remove:'앞표지 제거'}[draft.action]}${draft.sha256?' · SHA256 '+draft.sha256:''}`));
  }if(plan)row.append(text('p',plan.state==='READ_ONLY_COVER_PLAN'?'계획 확인 완료 · plan_id '+plan.plan_id:'HOLD: '+(plan.reason||'계획 확인 실패'),'tag-cover-hash'));current.append(row);}
 }
 async function inspectChosen(){sync();const chosen=[...selected()],ticket=version,id=albumId;if(!chosen.length||chosen.length>10)return;busy=true;render();try{for(const file of chosen){let r;try{r=await api('/api/cover/inspect',{album_id:id,file});}catch(e){r={state:'HOLD',reason:e.message};}if(ticket!==version)return;states.set(file,r);} }finally{busy=false;render();}}
 async function makePlans(){sync();const chosen=[...selected()],ticket=version,id=albumId;if(!draft||!chosen.length||chosen.length>10)return;busy=true;render();try{for(const file of chosen){const state=states.get(file);if(state?.state!=='EMBEDDED_COVER_INSPECTED'){plans.set(file,{state:'HOLD',reason:'현재 내장 커버를 먼저 조회하세요.'});continue;}let r;try{r=await api('/api/cover/plan',{album_id:id,file,action:draft.action,expected_file_sha256:state.file_sha256,expected_catalog_digest:state.catalog_digest,...(draft.action==='remove'?{}:{image_base64:draft.base64})});}catch(e){r={state:'HOLD',reason:e.message};}if(ticket!==version)return;plans.set(file,r);} }finally{busy=false;render();}}
 async function choose(file,action){if(!file)return;const ticket=++version;plans.clear();if(!['image/jpeg','image/png'].includes(file.type)||!file.size||file.size>10*1024*1024){reset();status.textContent='JPG·PNG 10MB 이하만 허용합니다.';return;}const url=URL.createObjectURL(file);try{const photo=new Image();photo.src=url;await photo.decode();const {naturalWidth:width,naturalHeight:height}=photo;if(!width||!height||width>4096||height>4096||width*height>16_000_000)throw Error('커버는 최대 4096px, 1600만 화소까지 허용합니다.');const buffer=await file.arrayBuffer(),hash=await crypto.subtle.digest('SHA-256',buffer);const base64=await new Promise((resolve,reject)=>{const fr=new FileReader();fr.onload=()=>resolve(String(fr.result).split(',')[1]);fr.onerror=reject;fr.readAsDataURL(file);});if(ticket!==version||!albumId){URL.revokeObjectURL(url);return;}revoke();objectUrl=url;draft={action,filename:file.name,width,height,bytes:file.size,url,base64,sha256:[...new Uint8Array(hash)].map(x=>x.toString(16).padStart(2,'0')).join('')};render();}catch(e){URL.revokeObjectURL(url);reset();status.textContent=e.message||'이미지 디코딩 실패';}}
 region.addEventListener('click',e=>{const action=e.target.closest('[data-cover-action]')?.dataset.coverAction;if(action==='add'||action==='replace'){if(!selected().length)return;intent=action;fileInput.click();}else if(action==='remove'){reset();draft={action:'remove'};render();}else if(e.target.closest('[data-cover-reset]'))reset();else if(e.target.closest('[data-cover-inspect]'))void inspectChosen();else if(e.target.closest('[data-cover-plan]'))void makePlans();});
 fileInput.addEventListener('change',()=>{const action=intent,file=fileInput.files?.[0];intent=null;fileInput.value='';if(action)void choose(file,action);});
 document.querySelector('.track-panel')?.addEventListener('change',()=>queueMicrotask(render));
 new MutationObserver(render).observe(albumHeader,{childList:true});render();return {refresh:render,clear:reset};
}
